<main class="section"><div class="section-head"><div><span class="eyebrow">Auftrag #<?=App\Core\View::e($order['order_number'])?></span><h1><?=App\Core\View::e($order['title'])?></h1><p class="muted"><?=App\Core\View::e($order['first_name'].' '.$order['last_name'])?> · <?=App\Core\View::e($order['email'])?> · <?=App\Core\View::e($order['status'])?></p></div><a class="btn" href="/admin">Dashboard</a></div>
<?php if(!$order['started_at']):?><form method="post" action="/admin/auftraege/<?=$order['id']?>/vorab-freigeben"><?=App\Core\Csrf::field()?><button class="btn primary">Vorabkontrolle vollständig freigeben & Auftrag starten</button></form><?php endif;?>
<section><h2>Nachweise</h2><div class="media-grid"><?php foreach($evidences as $e):?><div class="card media-card"><img src="/media/evidence/<?=$e['id']?>" alt="Nachweis"><div><b><?=App\Core\View::e($e['evidence_type'])?></b><span><?=date('d.m.Y H:i',strtotime($e['created_at']))?> · <?=App\Core\View::e($e['review_status'])?></span><form method="post" action="/admin/auftraege/<?=$order['id']?>/nachweise/<?=$e['id']?>/pruefen" class="review-form"><?=App\Core\Csrf::field()?><select name="decision"><option value="accepted">Akzeptieren</option><option value="rejected">Beanstanden</option></select><select name="reason"><option value="">Grund</option><option>unscharf</option><option>zu dunkel</option><option>falscher Bildausschnitt</option><option>Produkt nicht vollständig sichtbar</option><option>falsches Motiv</option><option>falsches Timing</option></select><input name="note" placeholder="Hinweis / benötigte Perspektive"><button class="btn">Speichern</button></form></div></div><?php endforeach;?></div></section>
<section><h2>Verstöße</h2><div class="worklist"><?php foreach($violations as $v):?><div class="work-row"><div><b><?=App\Core\View::e($v['violation_type'])?></b><span><?=App\Core\View::e($v['description'])?> · <?=App\Core\View::e($v['status'])?></span></div><?php if(!in_array($v['status'],['confirmed','discarded'],true)):?><form method="post" action="/admin/auftraege/<?=$order['id']?>/verstoesse/<?=$v['id']?>" class="row-actions"><?=App\Core\Csrf::field()?><button class="btn primary" name="decision" value="confirmed">Bestätigen +1 Tag</button><button class="btn" name="decision" value="discarded">Verwerfen</button></form><?php endif;?></div><?php endforeach;?><?php if(!$violations):?><div class="empty">Keine Verstöße.</div><?php endif;?></div></section>
<section class="card admin-form"><h2>Manueller Zusatztag</h2><form method="post" action="/admin/auftraege/<?=$order['id']?>/zusatztage" class="form-grid"><?=App\Core\Csrf::field()?><label class="full">Vollständiger Grund<textarea name="reason" rows="2" required></textarea></label><label class="check"><input type="checkbox" name="is_paid" value="1"> Bezahlt</label><label>Betrag (€)<input name="amount" type="number" step="0.01" min="0"></label><button class="btn primary full">Zusatztag anhängen</button></form></section>
<section><h2>Kalender / Tage</h2><div class="day-grid"><?php foreach($days as $d):?><div class="card day-card"><span><?=date('d.m.Y',strtotime($d['calendar_date']))?></span><strong><?=App\Core\View::e($d['day_type'])?><?=isset($d['day_no'])?' · '.$d['day_no']:''?></strong><small><?=App\Core\View::e($d['reason']??'')?></small></div><?php endforeach;?></div></section>
<section class="card chat"><h2>Auftragschat</h2><div class="chat-log"><?php foreach($messages as $m):?><div class="message <?=$m['sender_type']?>"><small><?=App\Core\View::e($m['sender_type'])?> · <?=date('d.m. H:i',strtotime($m['created_at']))?></small><p><?=nl2br(App\Core\View::e($m['message']))?></p></div><?php endforeach;?></div><form method="post" action="/admin/auftraege/<?=$order['id']?>/chat" class="chat-form"><?=App\Core\Csrf::field()?><textarea name="message" rows="3" required></textarea><button class="btn primary">Senden</button></form></section></main>